# Focus: Bias, Fairness, and Responsible Outputs
group_results = {"group_a": [1,1,0,1], "group_b": [1,0,0,0]}
rates = {group: sum(values)/len(values) for group,values in group_results.items()}
print({group: round(rate, 2) for group,rate in rates.items()})
# Differences are a review signal, not a complete fairness conclusion.
